/**
 * Builds a live OS total from manually confirmed costs and structured services.
 * Costs generated by the consolidation RPC mirror those services in `costs`,
 * so they must not be counted a second time here.
 */
export function buildCostComposition({ costs = [], tickets = [], hotels = [], vehicles = [], meals = [], laundry = [], uber = [] } = {}) {
  const rows = [];
  costs.filter(item => !String(item.source || "").startsWith("auto:")).forEach(item => {
    rows.push({
      category: item.category,
      amount: Number(item.amount || 0),
      collaborator_id: item.collaborator_id,
      source: item.source || "manual",
      description: item.description || ""
    });
  });
  tickets.forEach(item => {
    rows.push({ category: "ticket", amount: Number(item.cost || 0), collaborator_id: item.collaborator_id, source: "ticket", description: item.description || "Passagem" });
    if (item.baggage_included) rows.push({ category: "baggage", amount: 0, collaborator_id: item.collaborator_id, source: "ticket", description: `Bagagem: ${item.baggage_quantity || 0}` });
  });
  hotels.forEach(item => rows.push({ category: "hotel", amount: Number(item.cost || 0), source: "accommodation", description: item.provider || "Hospedagem" }));
  vehicles.filter(item => item.required).forEach(item => {
    [["vehicle", item.rental_cost], ["toll", item.toll_cost], ["parking", item.parking_cost], ["other", item.other_cost]].forEach(([category, amount]) => {
      if (Number(amount || 0) > 0) rows.push({ category, amount: Number(amount), source: "vehicle", description: category });
    });
  });
  meals.forEach(item => rows.push({ category: "meal", amount: Number(item.unit_cost || 0) * Number(item.quantity || 1), collaborator_id: item.collaborator_id, source: "meal", description: item.meal_type }));
  laundry.filter(item => Number(item.period_days || 0) > 7).forEach(item => rows.push({ category: "laundry", amount: Number(item.cost || 0), collaborator_id: item.collaborator_id, source: "laundry", description: `Período ${item.period_days} dias` }));
  uber.forEach(item => rows.push({ category: "uber", amount: Number(item.amount || 0), collaborator_id: item.collaborator_id, source: "uber", description: item.description || "Uber" }));

  const byCategory = rows.reduce((totals, item) => {
    totals[item.category] = (totals[item.category] || 0) + item.amount;
    return totals;
  }, {});
  const byCollaborator = rows.reduce((totals, item) => {
    const key = item.collaborator_id || "sem-colaborador";
    totals[key] = (totals[key] || 0) + item.amount;
    return totals;
  }, {});
  return { rows, byCategory, byCollaborator, total: rows.reduce((sum, item) => sum + item.amount, 0) };
}
